import type {
  CreateTargetGroupData,
  TargetGroupListItemView,
  TargetGroupView,
  TargetGroupUserView,
  UpdateTargetGroupData,
} from "../types";

interface FindByOrganizationIdInput {
  search?: string;
  limit: number;
  offset: number;
